+      border-radius: 16px;
+    }
+
+    .checkbox-row {
+      display: flex;
+      align-items: flex-start;
+      gap: 12px;
+    }
+
+    input[type="checkbox"] {
+      margin: 2px 0 0;
+      width: 18px;
+      height: 18px;
+      accent-color: var(--accent);
+    }
+
+    input[type="checkbox"]:focus-visible,
+    button:focus-visible {
+      outline: 3px solid var(--accent-strong);
+      outline-offset: 3px;
+    }
+
+    label {
+      font-weight: 600;
+      line-height: 1.45;
+    }
+
+    .helper-text,
+    .status-message {
+      font-size: 0.95rem;
+      color: var(--muted);
