 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>
   <main id="main-content">
     <section class="card" aria-labelledby="form-title">
       <h1 id="form-title">Review and confirm</h1>
       <p>Please confirm that you agree before continuing.</p>

       <form id="consent-form" novalidate>
         <div class="form-field">
           <div class="checkbox-row">
             <input
               id="terms"
               name="terms"
               type="checkbox"
               required
               aria-describedby="terms-helper terms-error"
             >
             <label for="terms">I agree to the terms of use</label>
           </div>
           <p id="terms-helper" class="helper-text">Required to continue.</p>
           <p id="terms-error" class="error-message" aria-live="assertive"></p>
         </div>

         <button type="submit">Submit</button>
         <p id="form-status" class="status-message" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('consent-form');
     const checkbox = document.getElementById('terms');
     const errorMessage = document.getElementById('terms-error');
     const statusMessage = document.getElementById('form-status');

     function updateCheckboxState() {
       if (checkbox.checked) {
         checkbox.removeAttribute('aria-invalid');
         checkbox.setCustomValidity('');
         errorMessage.textContent = '';
         return;
       }

       checkbox.setAttribute('aria-invalid', 'true');
       checkbox.setCustomValidity('Please agree to the terms of use before submitting.');
       errorMessage.textContent = 'Please agree to the terms of use.';
     }

     checkbox.addEventListener('change', () => {
       statusMessage.textContent = '';
       updateCheckboxState();
     });

     form.addEventListener('submit', (event) => {
       updateCheckboxState();

       if (!form.checkValidity()) {
         event.preventDefault();
         checkbox.focus();
         return;
       }

       event.preventDefault();
       statusMessage.textContent = 'Consent recorded successfully.';
     });
   </script>
 </body>
 </html>

